import{_ as p,a0 as i,w as s,s as u,ao as l,I as n,x as t,a1 as r,A as a}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const T=JSON.parse('{"title":"如何在 Ubuntu 14/15 上配置 Apache Solr | LCTT x X-CMD","titleTemplate":false,"description":"如何在 Ubuntu 14/15 上配置 Apache Solr | LCTT (201601) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"如何在 Ubuntu 14/15 上配置 Apache Solr | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"如何在 Ubuntu 14/15 上配置 Apache Solr | LCTT (201601) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201601/20151123 How to Configure Apache Solr on Ubuntu 14 or 15","title":"如何在 Ubuntu 14/15 上配置 Apache Solr","tag":"201601","desc":""},"relativePath":"201601/20151123 How to Configure Apache Solr on Ubuntu 14 or 15.md","filePath":"[post].md"}'),d={name:"201601/20151123 How to Configure Apache Solr on Ubuntu 14 or 15.md"};function h(m,o,b,S,c,f){const e=i("Link");return s(),u("div",null,[o[21]||(o[21]=l(`<h1 id="如何在-ubuntu-14-15-上配置-apache-solr" tabindex="-1">如何在 Ubuntu 14/15 上配置 Apache Solr <a class="header-anchor" href="#如何在-ubuntu-14-15-上配置-apache-solr" aria-label="Permalink to “如何在 Ubuntu 14/15 上配置 Apache Solr”">​</a></h1><p>大家好，歡迎來閲讀我們今天這篇 Apache Solr 的文章。簡單的來説，Apache Solr 是一個最負盛名的開源搜索平台，配合運行在網站後端的 Apache Lucene，能夠讓你輕鬆創建搜索引擎來搜索網站、資料庫和文件。它能夠索引和搜索多個網站並根據搜索文本的相關內容返回搜索建議。</p><p>Solr 使用 HTTP 可擴展標記語言（XML），可以為 JSON、Python 和 Ruby 等提供應用程序接口(API)。根據Apache Lucene 項目所述，Solr 提供了非常多的功能，很受管理員們的歡迎：</p><ul><li>全文檢索</li><li>分面導航（Faceted Navigation）</li><li>拼寫建議/自動完成</li><li>自定義文檔排序/排列</li></ul><h4 id="前提條件" tabindex="-1">前提條件: <a class="header-anchor" href="#前提條件" aria-label="Permalink to “前提條件:”">​</a></h4><p>在一個使用最小化安裝包的全新 Ubuntu 14/15 系統上，你僅僅需要少量的準備，就開始安裝 Apache Solor.</p><h3 id="_1-system-update-系統更新" tabindex="-1">1)System Update 系統更新### <a class="header-anchor" href="#_1-system-update-系統更新" aria-label="Permalink to “1)System Update 系統更新###”">​</a></h3><p>使用一個具有 sudo 權限的非 root 用户登錄你的 Ubuntu 服務器，在接下來的所有安裝和使用 Solr 的步驟中都會使用它。</p><p>登錄成功後，使用下面的命令，升級你的系統到最新的更新及補丁：</p><pre><code>$ sudo apt-get update
</code></pre><h3 id="_2-安裝-jre" tabindex="-1">2) 安裝 JRE### <a class="header-anchor" href="#_2-安裝-jre" aria-label="Permalink to “2) 安裝 JRE###”">​</a></h3><p>要安裝 Solr，首先需要安裝 JRE(Java Runtime Environment)作為基礎環境，因為 solr 和 tomcat 都是基於Java.所以，我們需要安裝最新版的 Java 並配置 Java 本地環境.</p><p>要想安裝最新版的 Java 8，我們需要通過以下命令安裝 Python Software Properties 工具包</p><pre><code>$ sudo apt-get install python-software-properties
</code></pre><p>完成後，配置最新版 Java 8的倉庫</p><pre><code>$ sudo add-apt-repository ppa:webupd8team/java
</code></pre><p>現在你可以通過以下命令更新包源列表，使用‘apt-get’來安裝最新版本的 Oracle Java 8。</p><pre><code>$ sudo apt-get update

$ sudo apt-get install oracle-java8-installer
</code></pre><p>在安裝和配置過程中，點擊&#39;OK&#39;按鈕接受 Java SE Platform 和 JavaFX 的 Oracle 二進制代碼許可協議（Oracle Binary Code License Agreement）。</p><p>在安裝完成後，運行下面的命令，檢查是否安裝成功以及查看安裝的版本。</p><pre><code>kash@solr:~$ java -version
java version &quot;1.8.0_66&quot;
Java(TM) SE Runtime Environment (build 1.8.0_66-b17)
Java HotSpot(TM) 64-Bit Server VM (build 25.66-b17, mixed mode)
</code></pre><p>執行結果表明我們已經成功安裝了 Java，並達到安裝 Solr 最基本的要求了，接着我們進行下一步。</p><h3 id="安裝-solr" tabindex="-1">安裝 Solr### <a class="header-anchor" href="#安裝-solr" aria-label="Permalink to “安裝 Solr###”">​</a></h3><p>有兩種不同的方式可以在 Ubuntu 上安裝 Solr，在本文中我們只用最新的源碼包來演示源碼安裝。</p>`,24)),n("p",null,[o[1]||(o[1]=t("要使用源碼安裝 Solr，先要從",-1)),r(e,{href:"http://lucene.apache.org/solr/"},{default:a(()=>[...o[0]||(o[0]=[t("官網",-1)])]),_:1}),o[2]||(o[2]=t("下載最新的可用安裝包。複製以下鏈接，然後使用 'wget' 命令來下載。",-1))]),o[22]||(o[22]=l(`<pre><code>$ wget http://www.us.apache.org/dist/lucene/solr/5.3.1/solr-5.3.1.tgz
</code></pre><p>運行下面的命令，將這個已歸檔的服務解壓到 /bin 目錄。</p><pre><code>$ tar -xzf solr-5.3.1.tgz solr-5.3.1/bin/install_solr_service.sh --strip-components=2
</code></pre><p>運行腳本來啓動 Solr 服務，這將會先創建一個 solr 的用户，然後將 Solr 安裝成服務。</p><pre><code>$ sudo bash ./install_solr_service.sh solr-5.3.1.tgz
</code></pre><p><img src="http://blog.linoxide.com/wp-content/uploads/2015/11/12.png" alt="Solr 安裝"></p><p>使用下面的命令來檢查 Solr 服務的狀態。</p><pre><code>$ service solr status
</code></pre><p><img src="http://blog.linoxide.com/wp-content/uploads/2015/11/22.png" alt="Solr 狀態"></p><h3 id="創建-solr-集合" tabindex="-1">創建 Solr 集合: <a class="header-anchor" href="#創建-solr-集合" aria-label="Permalink to “創建 Solr 集合:”">​</a></h3><p>我們現在可以使用 Solr 用户添加多個集合。就像下圖所示的那樣，我們只需要在命令列中指定集合名稱和指定其配置集就可以創建多個集合了。</p><pre><code>$ sudo su - solr -c &quot;/opt/solr/bin/solr create -c myfirstcollection -n data_driven_schema_configs&quot;
</code></pre><p><img src="http://blog.linoxide.com/wp-content/uploads/2015/11/32.png" alt="創建集合"></p><p>我們已經成功的為我們的第一個集合創建了新核心實例目錄，並可以將數據添加到裏面。要查看庫中的默認模式文件，可以在這裏找到： &#39;/opt/solr/server/solr/configsets/data_driven_schema_configs/conf&#39; 。</p><h3 id="使用-solr-web" tabindex="-1">使用 Solr Web### <a class="header-anchor" href="#使用-solr-web" aria-label="Permalink to “使用 Solr Web###”">​</a></h3>`,15)),n("p",null,[o[5]||(o[5]=t("可以使用默認的端口8983連接 Apache Solr。打開瀏覽器，輸入 ",-1)),r(e,{href:"http://your"},{default:a(()=>[...o[3]||(o[3]=[t("http://your",-1)])]),_:1}),o[6]||(o[6]=t("_server_ip:8983/solr 或者 ",-1)),r(e,{href:"http://your-domain.com:8983/solr"},{default:a(()=>[...o[4]||(o[4]=[t("http://your-domain.com:8983/solr",-1)])]),_:1}),o[7]||(o[7]=t(". 確保你的防火牆允許8983端口.",-1))]),o[23]||(o[23]=l(`<pre><code>http://172.25.10.171:8983/solr/
</code></pre><p><img src="http://blog.linoxide.com/wp-content/uploads/2015/11/42.png" alt="Web訪問Solr"></p><p>在 Solr 的 Web 控制台左側菜單點擊 &#39;Core Admin&#39; 按鈕，你將會看見我們之前使用命令列方式創建的集合。你可以點擊 &#39;Add Core&#39; 按鈕來創建新的核心。</p><p><img src="http://blog.linoxide.com/wp-content/uploads/2015/11/52.png" alt="添加核心"></p><p>就像下圖中所示，你可以選擇某個集合並指向文檔來向裏面添加內容或從文檔中查詢數據。如下顯示的那樣添加指定格式的數據。</p><pre><code>{
&quot;number&quot;: 1,
&quot;Name&quot;: &quot;George Washington&quot;,
&quot;birth_year&quot;: 1989,
&quot;Starting_Job&quot;: 2002,
&quot;End_Job&quot;: &quot;2009-04-30&quot;,
&quot;Qualification&quot;: &quot;Graduation&quot;,
&quot;skills&quot;: &quot;Linux and Virtualization&quot;
}
</code></pre><p>添加文件後點擊 &#39;Submit Document&#39;按鈕.</p><p><img src="http://blog.linoxide.com/wp-content/uploads/2015/11/62.png" alt="添加文檔"></p><h3 id="總結" tabindex="-1">總結### <a class="header-anchor" href="#總結" aria-label="Permalink to “總結###”">​</a></h3><p>在 Ubuntu 上安裝成功後，你就可以使用 Solr Web 接口插入或查詢數據。如果你想通過 Solr 來管理更多的數據和文件，可以創建更多的集合。希望你能喜歡這篇文章並且希望它能夠幫到你。</p><hr>`,11)),n("p",null,[o[9]||(o[9]=t("via: ",-1)),r(e,{href:"http://linoxide.com/ubuntu-how-to/configure-apache-solr-ubuntu-14-15/"},{default:a(()=>[...o[8]||(o[8]=[t("http://linoxide.com/ubuntu-how-to/configure-apache-solr-ubuntu-14-15/",-1)])]),_:1})]),n("p",null,[o[13]||(o[13]=t("作者：",-1)),r(e,{href:"http://linoxide.com/author/kashifs/"},{default:a(()=>[...o[10]||(o[10]=[t("Kashif",-1)])]),_:1}),o[14]||(o[14]=t(" 譯者：",-1)),r(e,{href:"https://github.com/taichirain"},{default:a(()=>[...o[11]||(o[11]=[t("taichirain",-1)])]),_:1}),o[15]||(o[15]=t(" 校對：",-1)),r(e,{href:"https://github.com/carolinewuyan"},{default:a(()=>[...o[12]||(o[12]=[t("Caroline",-1)])]),_:1})]),n("p",null,[o[18]||(o[18]=t("本文由 ",-1)),r(e,{href:"https://github.com/LCTT/TranslateProject"},{default:a(()=>[...o[16]||(o[16]=[t("LCTT",-1)])]),_:1}),o[19]||(o[19]=t(" 原創編譯，",-1)),r(e,{href:"https://linux.cn/"},{default:a(()=>[...o[17]||(o[17]=[t("Linux中國",-1)])]),_:1}),o[20]||(o[20]=t(" 榮譽推出",-1))])])}const v=p(d,[["render",h]]);export{T as __pageData,v as default};
